const express = require('express');
const multer = require('multer');
const crypto = require('crypto');
const session = require('express-session');
const path = require('path');
const fs = require('fs');

const app = express();

app.use(session({
  secret: crypto.randomBytes(32).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'strict' }
}));

app.use(express.json());
app.use(express.urlencoded({ extended: false }));

const upload = multer({
  dest: '/tmp/ci-uploads/',
  limits: { fileSize: 50 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    const allowed = ['.tar.gz', '.zip', '.tgz'];
    const ext = path.extname(file.originalname).toLowerCase();
    if (allowed.includes(ext) || file.originalname.endsWith('.tar.gz')) {
      cb(null, true);
    } else {
      cb(new Error('Invalid file type'));
    }
  }
});

function generateCSRFToken(session) {
  if (!session.csrfSecret) {
    session.csrfSecret = crypto.randomBytes(32).toString('hex');
  }
  const timestamp = Date.now();
  const payload = `${session.csrfSecret}:${timestamp}`;
  const hmac = crypto.createHmac('sha256', session.csrfSecret).update(payload).digest('hex');
  return `${timestamp}.${hmac}`;
}

function validateCSRFToken(token, session) {
  if (!token || !session.csrfSecret) return false;
  const parts = token.split('.');
  if (parts.length !== 2) return false;
  const [timestamp, hmac] = parts;
  const ts = parseInt(timestamp, 10);
  if (isNaN(ts)) return false;
  // Token expires after 1 hour
  if (Date.now() - ts > 3600000) return false;
  const expectedPayload = `${session.csrfSecret}:${timestamp}`;
  const expectedHmac = crypto.createHmac('sha256', session.csrfSecret).update(expectedPayload).digest('hex');
  const hmacBuf = Buffer.from(hmac, 'hex');
  const expectedBuf = Buffer.from(expectedHmac, 'hex');
  // Guard against length mismatch which would make timingSafeEqual throw
  if (hmacBuf.length !== expectedBuf.length) return false;
  return crypto.timingSafeEqual(hmacBuf, expectedBuf);
}

function csrfProtection(req, res, next) {
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    return next();
  }
  const token = req.headers['x-csrf-token'] || req.body._csrf;
  if (validateCSRFToken(token, req.session)) {
    return next();
  }
  // For multipart uploads, still require CSRF token - no bypass for pipeline context
  if (req.headers['content-type'] && req.headers['content-type'].includes('multipart/form-data')) {
    const pipelineId = req.headers['x-pipeline-id'];
    if (pipelineId && isPipelineAuthorized(pipelineId, req.session)) {
      // Pipeline authorization alone is NOT sufficient - CSRF token still required
      return res.status(403).json({ error: 'CSRF token required even for authorized pipelines' });
    }
  }
  return res.status(403).json({ error: 'CSRF validation failed' });
}

function isPipelineAuthorized(pipelineId, session) {
  // Pipeline IDs are UUIDs generated by our system
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (!uuidRegex.test(pipelineId)) return false;
  // Check if this pipeline belongs to the user's active pipelines
  if (session.activePipelines && session.activePipelines.includes(pipelineId)) {
    return true;
  }
  return false;
}

const pipelineRegistry = new Map();

app.use(csrfProtection);

app.get('/api/csrf-token', (req, res) => {
  const token = generateCSRFToken(req.session);
  res.json({ token });
});

app.post('/api/pipeline/create', (req, res) => {
  if (!req.session.userId) return res.status(401).json({ error: 'Unauthorized' });
  const pipelineId = crypto.randomUUID();
  pipelineRegistry.set(pipelineId, {
    owner: req.session.userId,
    created: Date.now(),
    status: 'pending'
  });
  if (!req.session.activePipelines) req.session.activePipelines = [];
  req.session.activePipelines.push(pipelineId);
  res.json({ pipelineId });
});

app.post('/api/pipeline/:id/upload', upload.single('artifact'), (req, res) => {
  const pipelineId = req.params.id;
  if (!pipelineRegistry.has(pipelineId)) {
    return res.status(404).json({ error: 'Pipeline not found' });
  }
  const pipeline = pipelineRegistry.get(pipelineId);
  if (pipeline.owner !== req.session.userId) {
    return res.status(403).json({ error: 'Not your pipeline' });
  }
  if (pipeline.status === 'completed') {
    return res.status(400).json({ error: 'Pipeline already completed' });
  }
  if (!req.file) {
    return res.status(400).json({ error: 'No artifact provided' });
  }
  // Process the uploaded artifact
  const artifactPath = req.file.path;
  const artifactMeta = {
    originalName: path.basename(req.file.originalname),
    size: req.file.size,
    uploadedAt: Date.now(),
    checksum: computeChecksum(artifactPath)
  };
  pipeline.artifact = artifactMeta;
  pipeline.status = 'uploaded';
  res.json({ success: true, artifact: artifactMeta });
});

app.post('/api/pipeline/:id/trigger', (req, res) => {
  const pipelineId = req.params.id;
  if (!pipelineRegistry.has(pipelineId)) {
    return res.status(404).json({ error: 'Pipeline not found' });
  }
  const pipeline = pipelineRegistry.get(pipelineId);
  if (pipeline.owner !== req.session.userId) {
    return res.status(403).json({ error: 'Not your pipeline' });
  }
  if (!pipeline.artifact) {
    return res.status(400).json({ error: 'No artifact uploaded' });
  }
  // Trigger the CI/CD build
  pipeline.status = 'running';
  triggerBuild(pipelineId, pipeline);
  res.json({ success: true, status: 'running' });
});

function computeChecksum(filePath) {
  const content = fs.readFileSync(filePath);
  return crypto.createHash('sha256').update(content).digest('hex');
}

function triggerBuild(pipelineId, pipeline) {
  setTimeout(() => {
    pipeline.status = 'completed';
    console.log(`Pipeline ${pipelineId} completed`);
  }, 5000);
}

app.listen(3000, () => console.log('CI/CD service running on port 3000'));
